SELECT id, ticket_no, user_id, conversation_id, question, root_cause,
       status, assignee, reply, created_at, updated_at, resolved_at
FROM ai_ticket
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}

